--
-- Table structure for table `participant_item_details`
--

CREATE TABLE `participant_item_details` (
  `pi_id` double NOT NULL,
  `participant_id` double NOT NULL,
  `school_code` double NOT NULL,
  `admn_no` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `parent_admn_no` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0',
  `item_code` mediumint(9) NOT NULL,
  `item_type` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'S - Single, G - Group , P - Pinnany',
  `spo_id` smallint(6) NOT NULL DEFAULT 0 COMMENT 'Special order id',
  `spo_remarks` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `is_captain` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT 'N' COMMENT 'Y - Yes, N - No'
) ENGINE=MyISAM DEFAULT CHARSET=latin1 COLLATE=latin1_general_ci;

