--
-- Table structure for table `result_master`
--

CREATE TABLE `result_master` (
  `rm_id` double NOT NULL,
  `item_code` mediumint(9) NOT NULL,
  `participant_id` double NOT NULL,
  `school_code` double NOT NULL,
  `admn_no` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `code_no` mediumint(9) NOT NULL,
  `marks` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0',
  `total_mark` float NOT NULL,
  `percentage` float NOT NULL,
  `grade` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `point` smallint(6) NOT NULL,
  `rank` mediumint(9) NOT NULL,
  `is_taken` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT 'Y' COMMENT 'Y - Yes, N - No',
  `is_finish` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT 'N' COMMENT 'Y - Yes, N - No',
  `is_printed` smallint(1) NOT NULL,
  `is_certificate_printed` smallint(1) NOT NULL,
  `spo_id` mediumint(9) NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=latin2 COLLATE=latin2_general_ci;

