--
-- Table structure for table `z_participant_item_details_log`
--

CREATE TABLE `z_participant_item_details_log` (
  `pi_id` double NOT NULL,
  `participant_id` double NOT NULL,
  `school_code` double NOT NULL,
  `admn_no` varchar(10) NOT NULL,
  `parent_admn_no` varchar(10) NOT NULL,
  `item_code` mediumint(9) NOT NULL,
  `item_type` char(1) NOT NULL,
  `spo_id` smallint(6) NOT NULL,
  `spo_remarks` text DEFAULT NULL,
  `is_captain` char(1) NOT NULL,
  `ip` varchar(55) NOT NULL,
  `user_id` double NOT NULL,
  `status` char(1) NOT NULL,
  `time` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=MyISAM DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

